	var more = document.createElement('button');
	more.type = 'button';
	more.className = 'path-crumb path-more';
	var w = document.createElement('span');
	w.className = 'crumb-t';
	w.textContent = '\u2026';
	more.appendChild(w);
	var sep = cr[0].nextSibling.cloneNode(true);
