/// ⋯ differ only in their items, which `fill(item, sep, menu)` adds. An item with
/// no `run` is drawn disabled; one with `checked` is a checkbox. It hangs from
/// `anchor`'s right edge, or from (x, y) for a right-click or a long-press.
function openPop(key, anchor, label, fill, x, y) {
	if (pop && anchor && pop.anchor === anchor && pop.key === key) { closePop(); return; }	// a second press shuts it
	closePop();
	var menu = document.createElement('div');
	menu.className = 'railhead-menu';
	menu.dataset.menu = key.split(':')[0];
	menu.setAttribute('aria-label', label);
	function item(act, text, run, checked, title) {
		var it = document.createElement('button');
		it.type = 'button';
		it.className = 'railhead-menu-item';
		it.dataset.act = act;
		if (checked === undefined) {
			it.setAttribute('role', 'menuitem');
			it.textContent = text;
		} else {
			it.setAttribute('role', 'menuitemcheckbox');
			it.setAttribute('aria-checked', checked ? 'true' : 'false');
			it.classList.add('lead-ok');
			it.textContent = text;
		}
		if (title) it.title = title;
		if (run) it.addEventListener('click', function (ev) { ev.stopPropagation(); closePop(); run(); });
		else { it.disabled = true; it.setAttribute('aria-disabled', 'true'); }
		menu.appendChild(it);
		return it;
	}
	function sep() {
		var d = document.createElement('div');
		d.className = 'railhead-menu-sep';
		d.setAttribute('role', 'separator');
		menu.appendChild(d);
	}
	fill(item, sep, menu);
	pop = { el: menu, key: key, anchor: anchor };
	DaimondLayers.hang(menu, 'filesmenu', closePop, anchor);
	var r = anchor.getBoundingClientRect();
	var left = x !== undefined ? x : r.right - menu.offsetWidth;
	var top = y !== undefined ? y : r.bottom + 4;
	menu.style.left = Math.max(8, Math.min(left, window.innerWidth - menu.offsetWidth - 8)) + 'px';
	menu.style.top = Math.max(8, Math.min(top, window.innerHeight - menu.offsetHeight - 8)) + 'px';
	anchor.setAttribute('aria-expanded', 'true');
	setTimeout(function () { document.addEventListener('click', onPopOutside, true); }, 0);
}

/// The row ⋯: everything a row can do besides its ◈, each item only where it can act.
function openRowMenu(row, e, full, anchor, x, y) {
	var f = attachFocus();
	openPop('row:' + full, anchor, e.name, function (item, sep, menu) {
		menu.dataset.path = full;
		// UNBLOCK-24: the row's way into and out of what is in focus, said in words, first.
		// The ◈'s own press, so the two cannot disagree; a waiting mark is drawn at rest and
		// asked about from its ◈, and the Diamond's own folder is held, not added.
		var st = f ? attachStateOf(full, !!e.dir) : null;
		if (st && !st.own && !(st.on && st.away)) {
			var key = (st.on ? 'files.remove_from' : 'files.add_to')
				+ (f.kind !== 'diamond' ? '_chat' : f.name ? '' : '_diamond');
			item(st.on ? 'detach' : 'attach', t(key, f.kind === 'diamond' && f.name ? { name: f.name } : undefined),
				function () { pressMark(full, !!e.dir); });
		}
		// Residency, not location: a cloud row is the user's file, safe, simply not on
		// this device at the moment.
		var backed = !e.dir && !e.cloud && !!(window.DaimondCloud && DaimondCloud.manifest(full));
		if (e.cloud) {
			item('get', t('files.get'), function () { fetchEntry(full, e.size || 0); },
				undefined, t('files.get_help', { size: fmtFileBytes(e.size || 0) }));
		} else if (!e.dir) {
			item('download', t('files.download'), function () { downloadPath(full, false, e.name); },
				undefined, t('files.download_help'));
		}
		if (backed) {
			var pinned = DaimondCloud.isPinned(full);
			item('pin', t('files.pinned_short'), function () {
				DaimondCloud.pin(full, !DaimondCloud.isPinned(full));
				list(curDir);
			}, pinned, t(pinned ? 'files.pinned_help' : 'files.pin_help'));
			if (!pinned) item('free', t('files.free'), function () { freeEntry(full); }, undefined, t('files.free_help'));
		}
		// The grants beyond the ◈: only on the user's own mark, and only where it is in
		// force here can it be changed here (decision O2).
		var a = f && f.kind === 'diamond' ? attachedOf(rootedRef(e.dir ? 'dir' : 'file', full)) : null;
		if (a && isUsersMark(a.link)) {
			var why = (a.here === false || a.gone) ? t('dws.share_unavailable')
				: !a.force ? (a.by ? t('dws.confirm_here', { where: a.where }) : t('dws.confirm_old'))
				: (a.rowShare && !a.share) ? t('dws.shared_there') + '\n' + t('dws.share_here_help')
				: t('dws.share') + '\n' + t('dws.share_help', { max: fmtSyncBytes(SYNC_FOLDER_SHARE_MAX) });
			var can = a.here !== false && !a.gone && !!a.force;
			item('share', t('dws.share_item'), can ? function () { toggleAttachShare(a); } : null, a.share, why);
			if (a.force) item('readonly', t('dws.readonly'), function () { setReadOnly(a); }, a.ro);
		}
		item('rename', t('files.rename_move'), function () { renameEntry(e, full); });
		item('delete', t('files.delete'), function () { deleteEntry(e, full); });
	}, x, y);
}

/// Read only, from the row ⋯: the mark is written again with the other relation,
/// as a press here, and the row it replaces goes. A shared mark stays shared.
async function setReadOnly(a) {
	var l = a.link, id = l.owner;
	var rel = l.rel === 'consulted' ? 'holds' : 'consulted';
	try {
		var row = await ownLinkById(id, await diamondApp().add_link(id, 'diamond:' + id,
			l.other || l.to, rel, l.note || '', 'user', l.share === true));
		if (!row || !DaimondMarksHere.grant(id, row, rootHere(), { share: !!a.share })) marksNotSaved();
		else {
			try { await removeLinkHere(l); }
			catch (e) { dropRefused(e); }
		}
	} catch (e) { /* the repaint tells the truth */ }
	signalLinksChanged();
}

/// Save a file to this machine from its bytes, with the format's own media type.
/// Each chunk becomes its own Blob at once, so the JS heap holds one chunk rather
/// than the file: the browser may spill a Blob to disk and an array of
/// Uint8Arrays cannot be.
async function downloadPath(path, store, name, info, msgEl) {
	try {
		if (!info) info = await DaimondViewer.probe(path, { store: store });
		var parts = [], at = 0, CH = 4 * 1024 * 1024, size = (info && info.size) || 0;
		while (at < size) {
			var b = store ? await Wasm.store_read_bytes(path, at, CH) : await Wasm.read_bytes(path, at, CH);
			if (!b || !b.length) break;
			parts.push(new Blob([b]));
			at += b.length;
		}
		DaimondViewer.handOver(new Blob(parts, { type: (info && info.mime) || 'application/octet-stream' }),
			'', name || path.split('/').pop() || 'file');
	} catch (e) { noteFolderLost(e); fileMsg(friendlyError(e), true, msgEl); }
}

/// Delete a tree row's file or folder, confirmed, with a five-second way back for
/// a file.
async function deleteEntry(e, full) {
	var msg = t(e.dir ? 'files.delete_folder_body' : 'files.delete_file_body',
		{ name: e.name });
	if (!await confirmDialog(msg, t('files.delete'))) return;
	// WHAT WAS THERE, read before it goes (contract §8). A file can be
	// written back from its bytes; a FOLDER cannot, so only a file gets
	// the window and a folder keeps the confirm it already had. An
	// unreadable file gets no window either, rather than an Undo button
	// that would do nothing when pressed.
	// THE BYTES, NOT THE TEXT (release 5.1 QA round 3, FP): read as text and
	// written back with `file_write`, a PNG or a PDF came back corrupt and a
	// `.docx` became a new document of its text.
	var was = null;
	if (!e.dir) {
		try { was = await Wasm.read_bytes(full, 0, 4294967295); }
		catch (err) { was = null; }
		// And the version's `was`, marked before the delete as the Doc panel's save
		// marks (2026-09-25): a file the store had never seen left no row at all.
		var vb = versionsPath(full);
		if (vb && window.DaimondVersions && DaimondVersions.dirtyBefore) {
			await DaimondVersions.dirtyBefore(vb.id, vb.rel);
		}
	}
	// The result used to be discarded, so a failed directory
	// delete looked exactly like a successful one: the user
	// confirmed a destructive action and was told nothing.
	//
	// A FOLDER GOES THROUGH ITS OWN DOOR, never the tool. `file_delete`
	// took a `recursive` flag for this button, and every model could
	// pass it too: on 2026-09-22 a daimon removed ~4,900 of the owner's
	// files with it. The tool now removes one file, and the confirmed
	// folder delete is `Wasm.delete_folder`, which no tool call can name.
	var res;
	if (e.dir) {
		try { await Wasm.delete_folder(full); res = { outcome: 'done' }; }
		catch (err) { res = { outcome: 'failed', text: String(err && err.message || err) }; }
	} else {
		res = await tools().run_tool_outcome('file_delete', JSON.stringify({ path: full }));
	}
	if (!res || res.outcome !== 'done') {
		fileMsg(t('files.delete_failed', { name: e.name, reason: toolReason(res) }), true);
	} else {
		nudgeSync();	// a quiet delete must travel like any edit
		// The deletion is a user door, so it marks the path dirty: the
		// next turn's `user` manifest records that the file went, and the
		// body it had is in the version before it.
		var vp = versionsPath(full);
		if (vp && window.DaimondVersions) DaimondVersions.dirty(vp.id, vp.rel);
		if (was !== null) {
			undoAble(t('undo.deleted', { name: e.name }), function () {
				var back = tools().write_file_bytes
					? tools().write_file_bytes(full, was)
					: tools().run_tool_outcome('file_write',
						JSON.stringify({ path: full, content: new TextDecoder().decode(was) }));
				back.then(function () {
						if (vp && window.DaimondVersions) DaimondVersions.dirty(vp.id, vp.rel);
						nudgeSync();
						list(curDir);
					}, function () { /* the fence refused; the row says so on the next list */ });
			});
		}
	}
	list(curDir);
}

/// Bring a cloud-only file down. A fetch moves real bytes and, once
/// storage is priced, spends the user's credits, so a large one is
/// confirmed rather than assumed — the same reason the agent must ask
/// for it by name instead of having it appear under a read.
var FETCH_CONFIRM_OVER = 8 * 1024 * 1024;
async function fetchEntry(path, size, thenOpen) {
	if (!window.DaimondCloud) return;
	if (size > FETCH_CONFIRM_OVER) {
		var ok = await confirmDialog(
			t('files.fetch_body', { path: path, size: fmtFileBytes(size) }),
			t('files.fetch'));
		if (!ok) return;
	}
	fileMsg(t('files.fetching', { path: path }));
	var res = await DaimondCloud.fetch(path);
	// The tool's own answer, which on a failure is an fe2o3 chain. Through
	// friendlyError so it arrives as a sentence rather than as frames.
	if (res.indexOf('OK') !== 0) { fileMsg(friendlyError(res), true); return; }
	await list(curDir);
	if (thenOpen) openFile(path);
}

/// Drop this device's copy, keeping the file in cloud storage.
async function freeEntry(path) {
	if (!window.DaimondCloud) return;
	var res = await DaimondCloud.evict(path);
	var bad = res.indexOf('OK') !== 0;
	fileMsg(bad ? friendlyError(res) : res, bad);
	list(curDir);
}

/// Show a binary file as what it is: something to save, not something to
/// read. The workspace carries these now, so the panel has to meet one
/// without spilling a screen of replacement characters.
/// Wire the paperclip that attaches the open file to whatever is in focus
/// (ATTACH_CONTRACT.md §4): a permanent `holds` link for a Diamond, or
/// this turn only for an ordinary chat, and hidden with neither open.
///
/// A Diamond's own attachments are otherwise harvested at a fold, from
/// what a turn WROTE. That is right for everything an agent produces and
/// no use at all for the work a person brought with them, which is most
/// of what a Diamond is for. This writes the link there and then: a fold
/// is the moment the user blesses what an AGENT did, and there is
/// nothing to bless when the user is the one doing it. It says `holds`,
/// not `produced` -- the Diamond did not make this file.
///
/// Shared by the text view and the viewer, because a PDF somebody dropped in is
/// exactly the kind of thing worth attaching, and a button that appeared over
/// a `.md` and vanished over a `.pdf` would read as a bug.
///
/// # Arguments
/// * `path` - The file on screen.
/// * `holdBtn` - The button, or null where the view has none.
async function wireHold(path, holdBtn) {
	if (!holdBtn) return;
	holdBtn.classList.add('attach-btn');
	holdBtn.dataset.act = 'attach';
	// A word, not the outline icon `ACTION_ICONS.attach` draws for a file
	// ROW: this is the Doc/Preview panel's own toolbar, where Edit, Download
	// and Back all say what they do, and the paperclip carried no visible
	// label of its own at all (2026-09-29, owner).
	holdBtn.textContent = t('files.attach');
	async function paint() {
		var f = attachFocus();
		if (!f) { holdBtn.style.display = 'none'; return; }
		holdBtn.style.display = '';
		var on = false, away = false, where = '', confirm = false, old = false;
		if (f.kind === 'diamond') {
			// A FRESH READ (`heldLink`), never `attachStateOf`: this button can be
			// painted before the tree has ever been listed for this Diamond, and
			// `attachStateOf` reads the tree's own cache (`attached`/`ownHeld`),
			// which is empty until then.
			var link = await heldLink(f.id, path);
			on = !!link;
			// A MARK not in force here: the press asks to confirm it, and the button says
			// so. Only a mark: a row that grants nothing -- one on a file in the Diamond's
			// own directory, Keep's transcript among them (M1) -- is held, not away.
			if (link && isUsersMark(link) && !markInForce(link)) {
				away = true;
				confirm = markWaiting(link);
				old = confirm && !link.by;
				where = refWhere(link.other);
			}
		} else {
			// THE TREE'S OWN TEST (open item 4, 2026-09-25). This used to work `away`
			// out from the FRESH reference (`refReachable(rootedRef(...))`) rather
			// than the STORED one, so a holding pressed on another device, or never
			// confirmed here, never drew as waiting -- only as held. `attachStateOf`
			// asks `DaimondMarksHere.chatWaiting` of the stored row, as the tree does,
			// and carries no staleness risk here: a chat's holdings live on the chat
			// record itself, with no separate cache to be behind.
			var cst = attachStateOf(path, false);
			on = cst.on; away = cst.away; where = cst.where; confirm = !!cst.confirm;
		}
		holdBtn.classList.toggle('on', on);
		holdBtn.classList.toggle('away', away);
		holdBtn.title = away
			? (old ? t('dws.confirm_old') : confirm ? t('dws.confirm_here', { where: where }) : t('dws.not_here', { where: where }))
			: t('attach.to_focus');
		holdBtn.setAttribute('aria-pressed', on ? 'true' : 'false');
		holdBtn.setAttribute('aria-label', holdBtn.title);
	}
	holdBtn.addEventListener('click', async function () {
		var f = attachFocus();
		if (!f) return;
		if (f.kind === 'diamond') {
			// The paperclip's own door, so a mark waiting here is confirmed by the
			// press rather than taken off, and every add and removal records it here.
			await toggleAttachHold(path, false);
			renderArtefacts();
		} else {
			chatAttachToggle(f.id, rootedRef('file', path), false, path);
		}
		paint();
	});
	await paint();
	// The focus, or its links, can change under an open file, and the
	// button names it either way.
	document.addEventListener('daimond-links-changed', paint);
	document.addEventListener('daimond-diamond-changed', paint);
}

/// Show a file that is not characters: a picture, a sound, a video, a PDF, a
/// table, a tree, or -- for anything with no viewer -- its bytes.
///
/// This replaces a panel that said "binary file, 2.1 MB" and offered a
/// download. That was honest and it was also the whole of what the app could
/// do with most of what a person owns. The floor is now a hex dump naming the
/// format, which is the difference between "unsupported" and "inspectable".
///
/// It goes to the PREVIEW panel, not the Doc panel, and the axis is exactly
/// the one `openFile` already routes on: `DaimondViewer.editable` asks
/// whether the file is characters somebody could change. If it is, it belongs
/// where the editor is; if it is not, what is on screen is a RENDERING of it,
/// which is what the Preview panel is for. So a PDF and the Markdown beside
/// it are both up at once instead of taking turns at one panel.
///
/// `pvFile` and `pvStore` are the preview's own; `curFile` and `curContent`
/// belong to the document and are deliberately untouched here.
export async function showViewedFile(path, info, store, label) {
	// `label` names the file for the reader when `path` is an internal STORE path a
	// person never typed -- a version-store body opened from a changed-files tile is
	// read from `diamonds/<id>/versions/b/<hash>` but should read as `code/x/b.png`
	// (S-HAND #4). The bytes are still read by `path`; only the caption changes.
	var shown = String(label || path);
	DaimondViewer.close();          // whatever was open lets go of its blob URLs
	// THE FILE OPENED TAKES THE PANEL FROM THE LIVE PAGES (PDF-PANEL, 12 Oct
	// 2026). One panel shows one thing. The live view used to keep running
	// behind the viewer: both drew in the same tile, and its next stand-in hid
	// the viewer, so opening `hachiko.pdf` beside `hachiko.typ` showed the
	// live layout of the source under the PDF's name -- the export could not
	// be seen in-app, and the viewer's Download went with it. A `.pdf` is a
	// document to read whatever sits beside it, so the watch stops here; ⚙
	// Compile on the source is what arms it again.
	try { if (window.DaimondTypstWatch) DaimondTypstWatch.stop(); }
	catch (e) { /* no live view is the ordinary case */ }
	pg.pvFile = path; pg.pvStore = !!store;
	docEmbed(false);
	pvEl.style.display = '';
	pvEl.innerHTML =
		'<div class="files-view-head">' +
		'  <span class="files-view-name"></span>' +
		'  <span>' +
		'    <button class="files-btn" data-act="download" title="' + esc(t('files.download_help')) + '">'
			+ esc(t('files.download')) + '</button>' +
		'    <button class="files-btn" data-act="attach" title="">' + esc(t('files.attach')) + '</button>' +
		'    <button class="files-btn lead-back" data-act="back">' + esc(t('files.back')) + '</button>' +
		'  </span>' +
		'</div>' +
		'<div class="files-view-msg" style="display:none"></div>' +
		'<div class="files-view-viewer"></div>';
	pvEl.querySelector('.files-view-name').textContent = shown;
	var nameEl = document.getElementById('pv-name');
	if (nameEl) nameEl.textContent = shown;
	DaimondPanels.markUsed('preview');
	DaimondPanels.show('preview');
	DaimondPanels.reflow();
	pvEl.querySelector('[data-act="back"]').addEventListener('click', closePreview);
	// The download is built from the bytes, with the format's own media type on
	// it. The text path's handler makes a `text/plain` Blob out of `curContent`,
	// which is null here -- it would have saved the word "null".
	pvEl.querySelector('[data-act="download"]').addEventListener('click', function () {
		downloadPath(path, pg.pvStore, shown.split('/').pop(), info, pvEl);
	});
	await wireHold(path, pvEl.querySelector('[data-act="attach"]'));
	await DaimondViewer.show(
		pvEl.querySelector('.files-view-viewer'), path, info,
		{
			store:   pg.pvStore,
			t:       t,
			wasm:    Wasm,
			// The viewer reads bytes through the module handed to it above, so its
			// failures are the panel's own direct calls by another name.
			onError: function (e) { noteFolderLost(e); fileMsg(friendlyError(e), true, pvEl); },
		});
}

/// Let the preview go: the pages, the bytes and every blob URL behind them.
///
/// The twin of `closeView`, which does the same for the document. Two panels,
/// two closers, and neither one takes the other's file off the screen.
export function closePreview() {
	// TWO HANDS REACH THIS FOR ONE CLICK -- this module's own listener on the
	// closer, and the panel engine's generic `[data-close]` binding through
	// `onUserHide` -- so the second call must find nothing left to do. That
	// used to cost nothing, because everything below was idempotent. It stopped
	// being free when the live view came to be STOPPED here: stopping puts the
	// `<embed>` back exactly as it was, and a second `docEmbed(false)` after
	// that took it away again, closing into a panel holding nothing at all.
	var holding = !!(pg._pdfUrl || pg._docPdf || pg.pvFile || watchedPath());
	if (!holding) { DaimondPanels.hide('preview'); return; }
	if (pg._pdfUrl) { URL.revokeObjectURL(pg._pdfUrl); pg._pdfUrl = null; }
	// The viewer mints a blob URL per picture, sound or page it shows, and a
	// blob URL holds its bytes until it is revoked. A session that opened
	// forty files would otherwise still be holding all forty.
	DaimondViewer.close();
	pvEl.style.display = 'none';
	pvEl.innerHTML = '';
	docEmbed(false);
	pg.pvFile = null; pg._docPdf = '';
	var n = document.getElementById('pv-name');
	if (n) n.textContent = '';
	// THE ONE PLACE A WATCH IS ENDED BY A PERSON, and it has to be said out
	// loud now that the pages merely LEAVING the screen is a pause rather than
	// a stop (js/typstwatch.js `poll`). Visibility cannot tell "he closed the
	// document" from "he is looking at the source for a moment", and on a
	// phone the second happens every time he saves; so the closer says which
	// one this is instead of the loop guessing from an element's rects.
	//
	// LAST, AFTER `docEmbed(false)`, and the order is the whole of what the
	// panel looks like afterwards: `stop` unmounts the live view, and
	// unmounting gives the embed back the inline `display` it had before the
	// pages stood in front of it. Stopping first and hiding second closed into
	// a panel holding nothing at all -- which `dev/verify_typstwatch.mjs`
	// check 7 reads, and which used to be right only by accident, because the
	// stop came from a poll a second after this function had finished.
	try { if (window.DaimondTypstWatch) DaimondTypstWatch.stop(); }
	catch (e) { /* no live view is the ordinary case */ }
	DaimondPanels.hide('preview');
}

/// Open `path` — in the Doc panel if it is characters, in the Preview panel
/// if what can be shown of it is a rendering.
///
/// WHICH PANEL IS DECIDED BY WHAT THE FILE IS, never by which seat happens to
/// be free. `main.typ` and `notes.md` are things to edit and go to the Doc
/// panel; `main.pdf`, a photograph and a hex dump are things to look at and
/// go to the Preview panel, beside whatever is being edited rather than over
/// it.
///
/// `opts.store` opens it from Daimond's OWN store rather than from the active
/// workspace. The distinction is not cosmetic: with a folder open, the two
/// roots hold DIFFERENT FILES under the same name, and `DAIMOND.md` is exactly
/// such a name. A store file read through the workspace door would show the
/// project's copy, and saving it would write the user's standing instructions
/// into the project.
export async function openFile(path, opts) {
	// Which door THIS open came through. It is only committed to `storeFile`
	// once the file is known to be the document panel's: a picture opened
	// from the store used to flip the flag under a text file still open in
	// the editor, so the next read, conflict check or save went to the wrong
	// root.
	var store = !!(opts && opts.store);
	// A document that is not on disk yet. Nothing is probed and nothing is
	// read: there is no file to ask about, and `readRaw` would throw. The path
	// is a PROPOSAL -- the file is made by the first Save, through the same
	// `file_write` every other save goes through, so a fence that would refuse
	// it refuses it there rather than here.
	var blank = !!(opts && opts.blank);
	// A SNAPSHOT opened from somewhere other than the live file: the
	// changed-files tile passes the version-store body for a file the live
	// workspace cannot read (a `code/…` path with no folder mounted lands in
	// OPFS, where it is not — see `_turnFileRow`). Nothing is probed or read;
	// the given text is shown read-only, because Save would write it back
	// through a root that does not hold the file.
	var provided = !!(opts && typeof opts.content === 'string');
	var readOnly = !!(opts && opts.readOnly);
	// ASK WHAT THE FILE IS BEFORE DECODING IT AS CHARACTERS.
	//
	// What was here asked `DaimondCloud.fileAt`, which resolves through the
	// cloud offload cache and not the workspace -- so for a file in the user's
	// own folder it answered null, the check below it never ran, and
	// `readRaw` handed the bytes to `String::from_utf8_lossy`. Every byte that
	// was not valid UTF-8 became U+FFFD and went into a <pre>. Opening a PDF
	// filled the panel with replacement characters, which made the app look
	// broken rather than the format look unsupported.
	//
	// It could not have worked even where it did run: it looked for a NUL in
	// the first 4 KB, and a PDF's header carries none.
	//
	// `file_probe` reads 512 bytes and answers with the format, from the magic
	// bytes AND the name, saying so when the two disagree.
	var info = null;
	try { if (!blank && !provided) info = await DaimondViewer.probe(path, { store: store }); }
	catch (e) {
		// A missing file falls through to the text path, which reports it
		// properly -- but the failure is SAID before it does. This catch used
		// to be empty, and an empty one turns every way the probe can fail
		// (a withdrawn folder grant, a path the jail refuses) into the same
		// screen of characters as a correct answer, with nothing anywhere to
		// tell the two apart. Two bugs in this project stayed hidden inside
		// catches shaped like this one.
		info = null;
		try { console.warn('Daimond: could not tell what "' + path + '" is; '
			+ 'showing it as characters. ' + ((e && e.message) ? e.message : e)); }
		catch (e2) { /* no console */ }
	}
	// THE PANEL ROUTES ON WHETHER THE FILE IS EDITABLE, NOT ON THE VIEWER'S
	// HANDLER. Routing on the handler sent every `.md` to the viewer's
	// markdown tier, which took the EDITOR away from `DAIMOND.md` and
	// `prompts/*.md` -- and this panel is where those are edited. Rendering
	// markdown prettily is a poor trade for being unable to change it.
	//
	// It asked `info.chars` instead, and that was too generous by exactly one
	// case. `chars` is a fact about 512 bytes -- "these decode as characters"
	// -- and a PDF with no binary comment and no compressed stream near its
	// front satisfies it, so clicking one put `%PDF-1.4` and the object table
	// on screen, numbered, in the editor. `DaimondViewer.editable` asks the
	// question the panel means, and the reasoning is set out there: a
	// `Makefile` still opens in the editor, and a PDF no longer does however
	// readable its header happens to be.
	//
	// `info &&` first, and not merely against a null dereference: with no
	// answer at all the honest move is the text path, whose own read reports
	// why the file could not be opened. The viewer would draw a header naming
	// no format over a dump of nothing.
	// The panel it lands in is stamped with whose it is: the turn that asked
	// (`opts.owner`, from `file_show`), or the open conversation for his own act.
	var who = (opts && typeof opts.owner === 'string') ? opts.owner : '';
	if (!blank && info && !DaimondViewer.editable(info)) {
		await showViewedFile(path, info, store);
		ownPanel('preview', who);
		return;
	}
	// Read through the door THIS open came through (passed to readRaw, not the module
	// flag), and commit `storeFile` only AFTER the content is in hand -- so a read
	// that throws cannot leave the flag flipped for the next open (S-HAND #4). This
	// open is the document's, so from here the door the editor, the conflict check and
	// the save all use is `store`.
	var content = provided ? opts.content : (blank ? '' : await readRaw(path, store));
	pg.storeFile = store;
	pg.curFile = path; pg.curContent = content; pg.editing = false;
	viewEl.style.display = '';
	var isTypst = /\.typ$/i.test(path);
	// TWO BUTTONS, AND THEY WRITE TO TWO DIFFERENT FILES. Compile lays the
	// document out here, in the page, and writes `<main>-preview.pdf`; Publish
	// runs the project's own script on the machine, which is what writes the
	// final `<main>.pdf`. They were one button writing one name, and that name
	// was the final's -- see `previewPdfPath`.
	var compileBtn = isTypst
		? '    <button class="files-btn lead-compile" data-act="compile" title="'
			+ esc(t('files.compile_help')) + '">' + esc(t('files.compile')) + '</button>'
		+ '    <button class="files-btn lead-publish" data-act="publish" title="'
			+ esc(t('files.publish_help')) + '">' + esc(t('files.publish')) + '</button>'
		: '';
	viewEl.innerHTML =
		'<div class="files-view-head">' +
		'  <span>' +
		compileBtn +
		'    <button class="files-btn" data-act="edit" title="' + esc(t('files.edit')) + '">'
			+ esc(t('files.edit')) + '</button>' +
		// Edit used to have no way out but Save. Backing out meant closing the
		// whole document and opening it again, which threw the edit away
		// without a word -- a one-way door into a mode that writes.
		'    <button class="files-btn" data-act="cancel-edit" title="' + esc(t('files.stop_editing'))
			+ '" style="display:none">' + esc(t('common.cancel')) + '</button>' +
		// Line numbers used to be a `#` in this row. They are now a toggle in
		// the panel's own header, where the rest of "how this is shown" lives
		// and where it can be reached without the toolbar in view.
		// Words, not glyphs, the whole row through -- Edit/Save, Download and
		// Attach (the paperclip carried no visible label at all) now say what
		// they do the same way Back always has (2026-09-29, owner).
		'    <button class="files-btn" data-act="download" title="' + esc(t('files.download')) + '">'
			+ esc(t('files.download')) + '</button>' +
		'    <button class="files-btn" data-act="attach" title="">' + esc(t('files.attach')) + '</button>' +
		'    <button class="files-btn lead-back" data-act="back">' + esc(t('files.back')) + '</button>' +
		'  </span>' +
		'</div>' +
		'<div class="files-view-msg" style="display:none"></div>' +
		'<div class="files-view-note" style="display:none"></div>' +
		'<pre class="files-view-body"></pre>';
	var nameEl = document.getElementById('doc-name');
	if (nameEl) nameEl.textContent = path;                 // escaped
	renderFileBody();
	DaimondPanels.markUsed('doc');       // it now has something to hold
	// A QUIET redraw refreshes the document where it stands and does not bring
	// the panel forward: see `reshow`, whose file may be off screen.
	if (!(opts && opts.quiet)) {
		docFilling++;
		try { DaimondPanels.show('doc'); } finally { docFilling--; }
		ownPanel('doc', who);			// a quiet redraw is the same file, still its owner's
	}
	DaimondPanels.reflow();
	viewEl.querySelector('[data-act="back"]').addEventListener('click', closeView);
	// ── Attaching a file to the open Diamond ──────────────────────
	//
	// Artefacts are otherwise harvested at a fold, from what a turn WROTE.
	// That is right for everything an agent produces and no use at all for
	// the work a person brought with them, which is most of what a Diamond
	// is for. This writes the link there and then: a fold is the moment the
	// user blesses what an AGENT did, and there is nothing to bless when
	// the user is the one doing it.
	//
	// It says `holds`, not `produced`. The Diamond did not make this file.
	await wireHold(path, viewEl.querySelector('[data-act="attach"]'));

	viewEl.querySelector('[data-act="download"]').addEventListener('click', function () {
		DaimondViewer.handOver(pg.curContent, 'text/plain', path.split('/').pop() || 'file.txt');
	});
	// Edit ⇄ Save: swap the <pre> for a textarea; Save writes via the
	// file_write tool (honouring the active workspace root — OPFS or FSA).
	var editBtn   = viewEl.querySelector('[data-act="edit"]');
	// A snapshot from the version store is not the live file, so it cannot be
	// saved back: hide Edit (and Compile/Publish, which also write) and name the
	// panel as a snapshot so the reader knows why.
	if (readOnly) {
		['edit', 'compile', 'publish'].forEach(function (act) {
			var b = viewEl.querySelector('[data-act="' + act + '"]');
			if (b) b.style.display = 'none';
		});
		var nEl = document.getElementById('doc-name');
		if (nEl) nEl.textContent = path + ' — ' + t('versions.snapshot');
	}
	/// Caption and tooltip together, because they were set apart and drifted.
	///
	/// `title` was written once, at build, and six later sites changed only
	/// `textContent` -- so hovering "✔ Save" said "Edit", and hovering
	/// "✕ Cancel" said "Stop editing". A button whose tooltip contradicts its
	/// face is worse than one with no tooltip: the reader believes the hover.
	/// One door now, so a seventh caption cannot desync.
	function sayEditBtn(mode) {
		var face = mode === 'saving' ? t('files.saving')
			: mode === 'edit'    ? t('files.edit')
			: t('common.save');
		editBtn.textContent = face;
		editBtn.title = mode === 'saving' ? t('files.saving')
			: mode === 'edit'    ? t('files.edit')
			: t('common.save');
		editBtn.setAttribute('aria-label', editBtn.title);
	}
	// AND THE STARTING STATE COMES THROUGH THE SAME DOOR. The markup above
	// sets a caption and a `title` and no `aria-label`, so a screen that had
	// been through Edit and back was not the screen it started as -- an
	// attribute the round trip ADDED. `verify_reversible` reads exactly that:
	// it found nothing on the Doc panel that returned the user to where they
	// were, because nothing could. One door for the first state as well as
	// every later one.
	sayEditBtn('edit');
	var cancelBtn = viewEl.querySelector('[data-act="cancel-edit"]');
	// Every word this head is built from, gathered where they can be said
	// again. `sayEditBtn` already owns the one button whose caption moves with
	// the state, so it is called with the state rather than with a guess:
	// relabelling mid-save must not put "Save" back over "Saving…".
	pg.docRelabel = function () {
		sayEditBtn(editBtn.disabled ? 'saving' : (pg.editing ? 'save' : 'edit'));
		cancelBtn.title = t('files.stop_editing');
		cancelBtn.setAttribute('aria-label', t('files.stop_editing'));
		cancelBtn.textContent = t('common.cancel');
		var dl = viewEl.querySelector('[data-act="download"]');
		if (dl) dl.title = t('files.download');
		var bk = viewEl.querySelector('[data-act="back"]');
		if (bk) bk.textContent = t('files.back');
	};

	/// Leave edit mode without writing, putting the read view back.
	function stopEditing() {
		var ta = viewEl.querySelector('.files-edit');
		if (ta) {
			var pre = document.createElement('pre');
			pre.className = 'files-view-body';
			ta.replaceWith(pre);
		}
		pg.editing = false;
		sayEditBtn('edit');
		editBtn.disabled = false;
		cancelBtn.style.display = 'none';
		renderFileBody();
	}
	cancelBtn.addEventListener('click', async function () {
		var ta = viewEl.querySelector('.files-edit');
		// Typed work is only thrown away on purpose. An untouched editor
		// closes without a question, because there is nothing to lose.
		if (ta && ta.value !== pg.curContent) {
			var go = await confirmDialog(
				t('files.unsaved_body', { path: path }),
				t('files.discard'),
				{ title: t('files.discard_title'), danger: true, cancelLabel: t('files.keep_editing') });
			if (!go) return;
		}
		draftDrop(path);	// thrown away on purpose is still thrown away
		stopEditing();
		fileMsg(t('files.editing_stopped'));
	});
	editBtn.addEventListener('click', async function () {
		if (!pg.editing) {
			pg.editing = true;
			var ta = document.createElement('textarea');
			ta.className = 'files-edit'; ta.value = pg.curContent; ta.spellcheck = false;
			// EVERY KEYSTROKE, not a debounce. The event this exists for is the
			// tab being killed, and a kill does not wait for a timer to fire --
			// whatever is held back at that moment is exactly what is lost.
			// Writing a chapter-sized string to localStorage is well under a
			// millisecond, which is a great deal less than the gap between two
			// characters typed by a person.
			ta.addEventListener('input', function () {
				draftKeep(path, ta.value, pg.curContent);
			});
			viewEl.querySelector('.files-view-body').replaceWith(ta);
			ta.focus();
			// At the TOP, not the end. Focusing a textarea leaves the caret past
			// the last character, and the box does not wrap -- so pressing Edit
			// scrolled five thousand pixels right, to the end of the longest line
			// in the file, and the document looked empty.
			ta.setSelectionRange(0, 0);
			ta.scrollTop = 0;
			ta.scrollLeft = 0;
			sayEditBtn('save');
			cancelBtn.style.display = '';
			syncLineNo();            // a textarea has no gutter to number
		} else {
			var ta2 = viewEl.querySelector('.files-edit'), content = ta2.value;
			editBtn.disabled = true; sayEditBtn('saving');
			// The agent may have rewritten this file since it was opened.
			// Saving the editor's stale copy would silently erase that work,
			// so a disk that no longer matches the edit's base is confirmed
			// before it is overwritten.
			var disk = null;
			try { disk = await readRaw(path); }
			catch (e) { /* new file, or unreadable; treat as no conflict */ }
			if (disk !== null && disk !== pg.curContent && disk !== content) {
				// In-app, not window.confirm: a native box is an OS dialog with
				// the origin in its title, styled nothing like the app, and it
				// blocks the page. This file says so at the top of its dialog
				// section, and this was the one place still doing it.
				var over = await confirmDialog(
					t('files.conflict_body'), t('files.overwrite'),
					{ title: t('files.conflict_title'), danger: true });
				if (!over) {
					editBtn.disabled = false; sayEditBtn('save');
					fileMsg(t('files.save_cancelled'), true);
					return;
				}
			}
			writeOpenFile(path, content).then(function (wr) {
				if (!wr || wr.outcome !== 'done') {
					editBtn.disabled = false; sayEditBtn('save');
					fileMsg(t('files.save_failed', { reason: toolReason(wr) }), true);
					return;
				}
				pg.curContent = content; pg.editing = false;
				draftDrop(path);	// it is on disk; there is nothing left to restore
				// It is a file now, so the two controls that act on one come back.
				['download', 'attach'].forEach(function (a) {
					var b = viewEl.querySelector('[data-act="' + a + '"]');
					if (b) b.style.display = '';
				});
				var pre = document.createElement('pre'); pre.className = 'files-view-body';
				ta2.replaceWith(pre);
				renderFileBody();
				sayEditBtn('edit'); editBtn.disabled = false;
				cancelBtn.style.display = 'none';
				fileMsg(t('files.saved')); refresh();
				nudgeSync();	// a saved edit outside a turn pushes on its own
				if (path === INSTRUCTIONS_FILE) Instructions.refresh();
				else if (path.indexOf(PROMPTS_DIR + '/') === 0) Prompts.refresh();
				if (pg.storeFile) sysList(sysDir);	// sizes move when a store file is saved
			}).catch(function (e) {
				editBtn.disabled = false; sayEditBtn('save');
				fileMsg(t('files.save_failed', { reason: friendlyError(e) }));
			});
		}
	});
	if (isTypst) {
		viewEl.querySelector('[data-act="compile"]').addEventListener('click', function () {
			compileTypst(path, this);
		});
		viewEl.querySelector('[data-act="publish"]').addEventListener('click', function () {
			publishViaDev(path, this);
		});
		// WHERE EACH OF THEM WOULD RUN, said on the button before it is pressed.
		// Not awaited: the buttons carry their plain words until the measurement
		// comes back, which is one probe of 29 stamps and a hash pass.
		renderDocSeat();
	}
	// A NEW DOCUMENT OPENS IN THE EDITOR, because a blank read view is a blank
	// panel and a blank panel is the whole defect. Through the button rather
	// than beside it, so the caret, the Cancel that backs out and the Save that
	// writes are the ones every other edit gets, and there is no second way in
	// to keep in step with the first.
	if (blank) {
		editBtn.click();
		// DOWNLOAD AND ATTACH ACT ON A FILE, and until the first Save there is
		// not one: the arrow would hand over an empty blob and the paperclip
		// would write a Diamond a link to a path that does not exist. They come
		// back the moment the document does -- see the save branch above.
		['download', 'attach'].forEach(function (a) {
			var b = viewEl.querySelector('[data-act="' + a + '"]');
			if (b) b.style.display = 'none';
		});
		// SAID ONCE, ON THE ROW THIS PANEL ALREADY TALKS ON: not a second
		// heading and not a second button. It says only what the title a line
		// above cannot -- which of the two filesystems this lands in, and that
		// it is Save and not time that puts it there. The place is the
		// Workspace panel's own word for it, because two surfaces calling one
		// place by two names is how a user comes to believe there are three.
		fileMsg(t('files.new_doc_here', { place: placeName() }));
	}
	// ── AND WHAT WAS TYPED LAST TIME AND NEVER SAVED ──────────────────
	//
	// Offered back rather than applied behind the reader's back: the editor
	// opens holding his own characters, the file on disk is untouched until he
	// presses Save, and one line says so. It goes through the Edit button for
	// the same reason a new document does -- the caret, the Cancel that backs
	// out and the Save that writes are then the ones every other edit gets.
	var kept = draftRead(path, pg.curContent);
	if (kept) {
		if (!pg.editing) editBtn.click();
		var ta0 = viewEl.querySelector('.files-edit');
		if (ta0) { ta0.value = kept.text; ta0.setSelectionRange(0, 0); }
		fileMsg(t('files.draft_restored'));
	}
}

export function install() { // page-split: install
	// page-split: install 38
	// The DOC panel's file, and nothing else's. A picture opened into the
	// Preview panel must not touch these: they are what the editor saves, what
	// the conflict check compares against and what the line-number toggle asks
	// about, and a PDF answering "no lines" for a Markdown file still open
	// beside it would be the split's first bug.
	/* var */ pg.curFile = null, pg.curContent = '';
	// page-split: install 39
	/* var */ pg.editing = false;   // a file is open in the editor with unsaved changes possible
	// page-split: install 40
	// SAY THE OPEN DOCUMENT'S TOOLBAR AGAIN, in whatever language is now on.
	//
	// The head is written once, as markup, by whichever of the three views is
	// showing -- so its captions, its tooltips and its spoken names are fixed at
	// the moment the file was opened. Nothing rebuilt them, because nothing rebuilds
	// a document somebody is reading: `Files.relabel` deliberately refuses to relist
	// while a file is open, since relisting closes it. The panel was therefore stuck
	// in the language it was opened in for as long as the document stayed, and once
	// the Doc panel gained a document at cold start, that was from the first paint.
	//
	// A slot rather than a redraw. A card is answered, not rebuilt: re-running
	// `openFile` would throw away an edit in progress, so each view leaves behind a
	// function that puts its own words right in place, and clearing the slot is how
	// a closed view says it has none.
	/* var */ pg.docRelabel = null;
	/* var */ showLineNos = localStorage.getItem('daimond-files-lineno') !== '0';
	// page-split: install 41
	/* var */ sysShown = (function () {
		try { return localStorage.getItem(LS_SYSSHOWN) === '1'; }
		catch (e) { return false; }
	})();
	// page-split: install 42
	/* var */ knowing = Promise.resolve();
	// page-split: install 43
	window.addEventListener('daimond:folder-lost', handlePermissionLoss);
	// page-split: install 44

	// What the tree last drew, as scope and folder. Reading the SAME one again keeps its
	// rows on screen until the new ones are ready: blanking them on every refresh threw
	// the scroll position away at the end of each turn. A different folder or scope
	// shows the loading row instead, so another place's rows are never left standing.
	/* var */ drawnKey = null;
	// page-split: install 45
	// Not drawn unless the device says otherwise (head ⋯, Show hidden files), so the
	// panel opens on the user's own files.
	/* var */ restShown = (function () {
		try { return localStorage.getItem(LS_RESTGROUP) === '1'; }
		catch (e) { return false; }
	})();
} // page-split: end install
